//! Frozen complete graph snapshots from the pinned OPSIN 2.9.0 dev oracle.
//! MIT Daniel Lowe/contributors; source b91b610af5ab07560fedb20730d7aef46bb2bca0.
//! Maven jar SHA256 627ee5da4af551f9c4d1d766f545eb7cf519a344776e0bb677247a47abac0252.
//! First 14 cases are name-built upstream graphs; final 7 are source resource
//! graphs after aromatic conversion and makeHydrogensExplicit. No name parser,
//! Java, network, or SMILES roundtrip is used by these Rust comparisons.
use opsin::{
    graph::{AtomId, BondId, Element, Graph},
    stereo_analyser,
};
fn integers(s: &str) -> Vec<usize> {
    if s.is_empty() {
        Vec::new()
    } else {
        s.split(',').map(|x| x.parse().unwrap()).collect()
    }
}
fn result_indices(result: Result<Vec<AtomId>, opsin::cip::CipOrderingError>) -> String {
    match result {
        Ok(atoms) => atoms
            .iter()
            .map(|a| a.0.to_string())
            .collect::<Vec<_>>()
            .join(","),
        Err(error) => format!("ERROR:{error}"),
    }
}
#[test]
fn exact_environments_centres_bonds_and_cip_adapters_on_upstream_complete_graphs() {
    assert_eq!(FROZEN.lines().count(), 21);
    for line in FROZEN.lines() {
        let p: Vec<_> = line.split('\t').collect();
        assert_eq!(p.len(), 9);
        let mut graph = Graph::default();
        let fragment = graph.add_fragment("");
        for record in p[1].split(';') {
            let a: Vec<_> = record.split(',').collect();
            let id = graph.add_atom(fragment, Element::from_symbol(a[0]).unwrap());
            let atom = graph.atom_mut(id);
            atom.isotope = if a[1] == "_" {
                None
            } else {
                Some(a[1].parse().unwrap())
            };
            atom.charge = a[2].parse().unwrap();
            atom.in_cycle = a[3] == "1";
            atom.implicit_hydrogen_allowed = a[4] == "1";
            atom.protons_explicitly_added_or_removed = a[5].parse().unwrap();
            atom.lambda_convention_valency = if a[6] == "_" {
                None
            } else {
                Some(a[6].parse().unwrap())
            };
            atom.minimum_valency = if a[7] == "_" {
                None
            } else {
                Some(a[7].parse().unwrap())
            };
        }
        for record in p[2].split(';') {
            let edge = integers(record);
            graph
                .add_bond(AtomId(edge[0]), AtomId(edge[1]), edge[2] as u8)
                .unwrap();
        }
        for (i, record) in p[6].split(';').enumerate() {
            graph.atom_mut(AtomId(i)).bonds = integers(record).into_iter().map(BondId).collect();
        }
        let before = graph.clone();
        let result = stereo_analyser::analyse(&graph, fragment).unwrap();
        assert_eq!(graph, before, "analysis mutated {}", p[0]);
        let colours: Vec<_> = graph
            .fragment(fragment)
            .atoms
            .iter()
            .map(|a| result.atom_environment_number(*a).unwrap())
            .collect();
        assert_eq!(colours, integers(p[3]), "environment colours: {}", p[0]);
        let centres: Vec<_> = result
            .centres
            .iter()
            .map(|c| vec![c.atom.0, usize::from(c.true_stereo_centre)])
            .collect();
        let expected: Vec<_> = if p[4].is_empty() {
            Vec::new()
        } else {
            p[4].split(';').map(integers).collect()
        };
        assert_eq!(centres, expected, "centres: {}", p[0]);
        assert_eq!(
            result.bonds.iter().map(|b| b.bond.0).collect::<Vec<_>>(),
            integers(p[5]),
            "stereo bonds: {}",
            p[0]
        );
        let expected_centre_cip: Vec<_> = if p[7].is_empty() {
            Vec::new()
        } else {
            p[7].split(';').collect()
        };
        assert_eq!(result.centres.len(), expected_centre_cip.len());
        for (centre, expected) in result.centres.iter().zip(expected_centre_cip) {
            assert_eq!(
                result_indices(centre.get_cip_ordered_atoms(&graph)),
                expected,
                "centre CIP: {}",
                p[0]
            );
        }
        let expected_bond_cip: Vec<_> = if p[8].is_empty() {
            Vec::new()
        } else {
            p[8].split(';').collect()
        };
        assert_eq!(result.bonds.len(), expected_bond_cip.len());
        for (bond, expected) in result.bonds.iter().zip(expected_bond_cip) {
            assert_eq!(
                result_indices(
                    bond.get_ordered_stereo_atoms(&graph)
                        .map(|atoms| atoms.to_vec())
                ),
                expected,
                "bond CIP: {}",
                p[0]
            );
        }
    }
}
